'use strict';
window.RevisionEMLV=(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const strategies=[
 [/actualis|VAN|investissement|échéance|annuit/i,'Placez les paiements sur un axe du temps. Distinguez le flux initial des flux futurs avant de les comparer.'],
 [/marge|rentabilit|ratio|taux|pourcentage/i,'Identifiez ce que vous mesurez et la grandeur à laquelle il faut le rapporter. Vérifiez la période et l’unité.'],
 [/trésorerie|encaiss|décaiss|flux/i,'Demandez-vous si de l’argent est réellement entré ou sorti pendant la période. Identifiez ensuite l’origine du mouvement.'],
 [/résultat|produit|charge|marcha|coût|ventes/i,'Repérez la période concernée. Distinguez la réalisation d’une vente ou d’une charge de son règlement.'],
 [/bilan|actif|passif|dette|créance|stock/i,'Raisonnez à la date de clôture : séparez les ressources détenues, les obligations envers les tiers et la part des propriétaires.']];
 const hint=q=>(strategies.find(x=>x[0].test(q))||[0,'Identifiez la décision demandée, les données pertinentes et leur unité.'])[1];
 function guide(h,html,q=''){const hs=[...new Set((Array.isArray(h)?h:[h]).filter(x=>typeof x==='string'&&x.trim()))].slice(0,2);if(!hs.length)hs.push(hint(q));let inner='<details class="er-answer"><summary>Voir la réponse expliquée</summary><div>'+html+'</div></details>';for(let i=hs.length-1;i>=0;i--)inner='<details class="er-step"><summary>'+(!i?'Voir un indice':'Voir le deuxième indice')+'</summary><p>'+esc(hs[i])+'</p>'+inner+'</details>';return '<div class="er-guide">'+inner+'</div>';}
 function sol(ans,why){return '<p><strong>Réponse :</strong> '+esc(ans)+'</p>'+(why?'<p><strong>Raisonnement :</strong> '+esc(why)+'</p>':'');}
 function mount(){const root=document.querySelector('[data-er-module]');if(!root)return;const rows=window.EMLV_CORRIGES?.[root.dataset.erModule]||[],bank=document.getElementById('er-bank');const link=root.querySelector('[data-er-bank]');if(rows.length&&bank){const groups=new Map();for(const [form,q,a,w,h] of rows){if(!groups.has(form))groups.set(form,[]);groups.get(form).push([q,a,w,h]);}bank.querySelector('.er-body').innerHTML=[...groups].map(([form,ls])=>'<details class="er-form"><summary>'+esc(form)+' · '+ls.length+' questions</summary>'+ls.map(([q,a,w,h],i)=>'<section><h3>'+String(i+1)+'. '+esc(q)+'</h3>'+guide(h,sol(a,w),q)+'</section>').join('')+'</details>').join('');link.onclick=()=>{bank.showModal();bank.querySelector('button').focus()};bank.querySelector('button').onclick=()=>bank.close();}else if(link)link.hidden=true;
 const via=new URL(location.href).searchParams.get('carnet');if(via==='export'||via==='import'){const button=root.querySelector('.er-'+via);button.focus();const info=document.createElement('span');info.setAttribute('role','status');info.textContent='Application ouverte. Cliquez sur « '+button.textContent+' » pour continuer.';root.append(info);const url=new URL(location.href);url.searchParams.delete('carnet');history.replaceState(history.state,'',url);}document.addEventListener('click',e=>{if(e.target.closest('[data-er-forms]')){e.preventDefault();link?.click();}});}
 document.addEventListener('DOMContentLoaded',mount);
 return {guide,sol,hint,esc};
})();

window.EMLV_CORRIGES={"dst":[["DST1 · EMLV · Validation · Validation · Papeterie des Rives","1. Quel document permet de retrouver les créances clients à la clôture N ?","Le bilan N","Réponse attendue : Le bilan N. Le bilan présente les droits et les dettes à une date donnée. Une vente déjà réalisée, mais non encaissée, y figure en créances clients.",[]],["DST1 · EMLV · Validation · Validation · Papeterie des Rives","2. Calculez le total de l’actif N.","1325 k€","Total actif = immobilisations + stocks + créances + disponibilités. Résultat attendu : 1325 k€.",["Bilan au 31 décembre, colonne(s) N : Immobilisations nettes, Stocks, Créances clients, Disponibilités.","Total actif = immobilisations + stocks + créances + disponibilités. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 372 + 147 + …"]],["DST1 · EMLV · Validation · Validation · Papeterie des Rives","[QCM q2 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le total de l’actif N ?","Immobilisations + stocks + créances + disponibilités","Total actif = immobilisations + stocks + créances + disponibilités. Dans le cas : 1 325 k€.",[]],["DST1 · EMLV · Validation · Validation · Papeterie des Rives","3. Calculez la variation des créances clients entre N-1 et N.","91 k€","Variation des créances = N − N-1. Résultat attendu : 91 k€.",["Bilan au 31 décembre, colonne(s) N-1 et N : Créances clients.","Variation des créances = N − N-1. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 249 − 158 ; gardez le signe."]],["DST1 · EMLV · Validation · Validation · Papeterie des Rives","[QCM q3 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la variation des créances clients entre N-1 et N ?","Créances à la clôture − créances à l’ouverture","Variation des créances = N − N-1. Dans le cas : 91 k€.",[]],["DST1 · EMLV · Validation · Validation · Papeterie des Rives","[QCM q4] Une vente à crédit est comptabilisée mais pas encore réglée. Pourquoi la créance figure-t-elle à l’actif ?","Elle représente un droit au paiement ; les disponibilités augmenteront au règlement.","La vente donne un droit sur le client. Au paiement, la créance diminue et la trésorerie augmente, sans constater une seconde vente.",[]],["DST2 · EMLV · Validation · Validation · Vestiaire des Arts","1. Calculez le coût des marchandises vendues N à partir du détail des marchandises.","714 k€","Coût vendu = stock initial + achats − stock final. Résultat attendu : 714 k€.",["Détail de l’activité d’achat-revente, colonne(s) N : Stock initial de marchandises, Achats de marchandises N, Stock final de marchandises.","Coût vendu = stock initial + achats − stock final. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 146 + 666 − …"]],["DST2 · EMLV · Validation · Validation · Vestiaire des Arts","[QCM q1 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le coût des marchandises vendues N à partir du détail des marchandises ?","Stock initial + achats − stock final","Coût vendu = stock initial + achats − stock final. Dans le cas : 714 k€.",[]],["DST2 · EMLV · Validation · Validation · Vestiaire des Arts","2. Calculez la marge commerciale N.","384 k€","Marge commerciale = ventes de marchandises − coût vendu. Résultat attendu : 384 k€.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises. Détail de l’activité d’achat-revente, colonne(s) N : Stock initial de marchandises, Achats de marchandises N, Stock final de marchandises.","Marge commerciale = ventes de marchandises − coût vendu. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 1 098 − le coût vendu calculé à la question précédente."]],["DST2 · EMLV · Validation · Validation · Vestiaire des Arts","[QCM q2 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la marge commerciale N ?","Ventes de marchandises − coût des marchandises vendues","Marge commerciale = ventes de marchandises − coût vendu. Dans le cas : 384 k€.",[]],["DST2 · EMLV · Validation · Validation · Vestiaire des Arts","3. Quelle conclusion est correcte ?","La marge doit encore contribuer à couvrir les autres charges.","Réponse attendue : La marge doit encore contribuer à couvrir les autres charges.. La marge commerciale retranche le coût des marchandises vendues des ventes de marchandises. Elle doit ensuite financer les autres charges ; elle est distincte du bénéfice net.",[]],["DST2 · EMLV · Validation · Validation · Vestiaire des Arts","[QCM q4] Que permettent de conclure les 384 k€ de marge commerciale ?","Les ventes couvrent le coût des marchandises vendues et laissent 384 k€ pour couvrir les autres charges.","La marge commerciale est la différence entre ventes de marchandises et coût des marchandises vendues. Les autres charges restent à couvrir.",[]],["DST3 · EMLV · Validation · Validation · Fabrique des Cèdres","1. Calculez la production de l’exercice N.","870 k€","Production = production vendue + production stockée + production immobilisée (nulle ici). Résultat attendu : 870 k€.",["Compte de résultat simplifié, colonne(s) N : Production vendue de biens et services, Production stockée.","Production = production vendue + production stockée + production immobilisée (nulle ici). Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 850 + 20 + …"]],["DST3 · EMLV · Validation · Validation · Fabrique des Cèdres","[QCM q1 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la production de l’exercice N ?","Production vendue + production stockée + production immobilisée","Production = production vendue + production stockée + production immobilisée (nulle ici). Dans le cas : 870 k€.",[]],["DST3 · EMLV · Validation · Validation · Fabrique des Cèdres","2. Calculez la valeur ajoutée N.","693 k€","VA = marge commerciale + production − matières consommées − autres consommations externes. Résultat attendu : 693 k€.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes.","VA = marge commerciale + production − matières consommées − autres consommations externes. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 278 + 870 − …"]],["DST3 · EMLV · Validation · Validation · Fabrique des Cèdres","[QCM q2 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la valeur ajoutée N ?","Marge commerciale + production − matières consommées − autres consommations externes","VA = marge commerciale + production − matières consommées − autres consommations externes. Dans le cas : 693 k€.",[]],["DST3 · EMLV · Validation · Validation · Fabrique des Cèdres","3. La production stockée correspond ici à…","Une variation de production non encore vendue","Réponse attendue : Une variation de production non encore vendue. La production stockée est la variation des stocks de produits de l’entreprise. Une unité produite mais non vendue peut augmenter la production de l’exercice sans générer une vente ni un encaissement.",[]],["DST3 · EMLV · Validation · Validation · Fabrique des Cèdres","[QCM q4] Le CA est de 1 546 k€ et la production de l’exercice de 870 k€. Pourquoi ces montants diffèrent-ils ?","Le CA inclut les marchandises revendues ; la production inclut 20 k€ de production stockée qui ne sont pas des ventes.","Une marchandise achetée et revendue entre dans le CA mais pas dans la production. Un bien produit et stocké entre dans la production sans entrer dans le CA.",[]],["DST4 · EMLV · Validation · Validation · Services Tramontane","1. Calculez la valeur ajoutée N.","1078 k€","VA = marge commerciale + production − consommations externes. Résultat attendu : 1078 k€.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes.","VA = marge commerciale + production − consommations externes. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 0 + 1 344 − …"]],["DST4 · EMLV · Validation · Validation · Services Tramontane","[QCM q1 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la valeur ajoutée N ?","Marge commerciale + production − consommations externes","VA = marge commerciale + production − consommations externes. Dans le cas : 1 078 k€.",[]],["DST4 · EMLV · Validation · Validation · Services Tramontane","2. Calculez l’EBE N.","358 k€","EBE = VA + subventions (nulles ici) − personnel − taxes d’exploitation. Résultat attendu : 358 k€.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation.","EBE = VA + subventions (nulles ici) − personnel − taxes d’exploitation. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 1 078 − 700 − …"]],["DST4 · EMLV · Validation · Validation · Services Tramontane","[QCM q2 – méthode] Méthode (hors barème) : quelle opération permet de déterminer l’EBE N ?","Valeur ajoutée + subventions d’exploitation − charges de personnel − impôts et taxes d’exploitation","EBE = VA + subventions (nulles ici) − personnel − taxes d’exploitation. Dans le cas : 358 k€.",[]],["DST4 · EMLV · Validation · Validation · Services Tramontane","3. Quel poste ne doit pas encore être déduit pour calculer l’EBE ?","Les dotations aux amortissements","Réponse attendue : Les dotations aux amortissements. Les dotations aux amortissements sont prises en compte après l’EBE pour déterminer le résultat d’exploitation. Les déduire plus tôt reviendrait à confondre les deux soldes.",[]],["DST4 · EMLV · Validation · Validation · Services Tramontane","[QCM q4] Le cas présente un EBE de 358 k€. Quelle lecture en faire ?","L’exploitation dégage un excédent avant amortissements et finance ; les décalages de paiement influencent la trésorerie.","L’EBE mesure une performance d’exploitation. Des ventes non encore encaissées peuvent y contribuer sans avoir alimenté la banque.",[]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","1. Quelle précaution de diagnostic est justifiée ?","Il faut croiser résultat, bilan et flux avant de conclure.","Réponse attendue : Il faut croiser résultat, bilan et flux avant de conclure.. Une perte ne donne pas à elle seule le solde bancaire : le bilan renseigne sur les ressources et les dettes, le tableau des flux sur les encaissements et les décaissements.",[]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","2. Calculez le résultat d’exploitation N.","-352 k€","RE = EBE − amortissements dans ce cas. Résultat attendu : -352 k€.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation, Dotations aux amortissements.","RE = EBE − amortissements dans ce cas. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : -330 − 22 ; terminez la soustraction."]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","[QCM q1 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le résultat d’exploitation N ?","EBE − dotations aux amortissements, en l’absence d’autres éléments d’exploitation","RE = EBE − amortissements dans ce cas. Dans le cas : -352 k€.",[]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","3. Calculez le résultat financier N.","-7 k€","RF = produits financiers − charges financières. Résultat attendu : -7 k€.",["Compte de résultat simplifié, colonne(s) N : Produits financiers, Intérêts et charges financières.","RF = produits financiers − charges financières. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 0 − 7 ; gardez le signe."]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","[QCM q2 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le résultat financier N ?","Produits financiers − charges financières","RF = produits financiers − charges financières. Dans le cas : -7 k€.",[]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","4. Calculez le RCAI N.","-359 k€","RCAI = RE + RF. Résultat attendu : -359 k€.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation, Dotations aux amortissements, Produits financiers, Intérêts et charges financières.","RCAI = RE + RF. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : -352 + (-7) ; additionnez un solde financier éventuellement négatif."]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","[QCM q3 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le RCAI N ?","Résultat d’exploitation + résultat financier","RCAI = RE + RF. Dans le cas : -359 k€.",[]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","5. Calculez le résultat net N.","-359 k€","RN = RCAI − impôt sur les bénéfices dans ce cas. Résultat attendu : -359 k€.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation, Dotations aux amortissements, Produits financiers, Intérêts et charges financières, Impôt sur les bénéfices.","RN = RCAI − impôt sur les bénéfices dans ce cas. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : -359 − 0 ; terminez la soustraction."]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","[QCM q4 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le résultat net N ?","Résultat courant avant impôt − impôt sur les bénéfices, en l’absence d’autres éléments","RN = RCAI − impôt sur les bénéfices dans ce cas. Dans le cas : -359 k€.",[]],["DST5 · EMLV · Validation · Validation · Comptoir Nouvelle Vie","[QCM q5] Un versement comprend 15 k€ de capital remboursé et 7 k€ d’intérêts. Quel traitement retenir ?","Les 15 k€ réduisent la dette et la trésorerie ; les 7 k€ sont une charge financière.","Le remboursement du principal règle une dette. Les intérêts rémunèrent le prêteur et affectent le résultat financier.",[]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","1. Quelle précaution de diagnostic est justifiée ?","Il faut croiser résultat, bilan et flux avant de conclure.","Réponse attendue : Il faut croiser résultat, bilan et flux avant de conclure.. La hausse des ventes et celle du résultat ne prouvent pas la même progression de trésorerie. Il faut les relier aux marges, au bilan et aux flux avant d’attribuer une cause.",[]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","2. Calculez le taux d’évolution du chiffre d’affaires entre N-1 et N.","7.1 %","Variation relative = (CA N − CA N-1) / CA N-1 × 100. Résultat attendu : 7,1 %.",["Compte de résultat simplifié, colonne(s) N-1 et N : Chiffre d’affaires.","Variation relative = (CA N − CA N-1) / CA N-1 × 100. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : (2 370 − 2 212) / 2 212 × …"]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","[QCM q1 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le taux d’évolution du chiffre d’affaires entre N-1 et N ?","(CA N − CA N−1) / CA N−1 × 100","Variation relative = (CA N − CA N-1) / CA N-1 × 100. Dans le cas : 7,1 %.",[]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","3. Calculez la variation du résultat net en montant.","52 k€","Variation du RN en montant = RN N − RN N-1. Résultat attendu : 52 k€.",["Compte de résultat simplifié, colonne(s) N-1 et N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation, Dotations aux amortissements, Produits financiers, Intérêts et charges financières, Impôt sur les bénéfices.","Variation du RN en montant = RN N − RN N-1. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 125 − (73) ; gardez le signe."]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","[QCM q2 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la variation du résultat net en montant ?","Résultat net N − résultat net N−1","Variation du RN en montant = RN N − RN N-1. Dans le cas : 52 k€.",[]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","4. Calculez le poids des charges de personnel dans le CA N.","16.3 %","Poids du personnel = personnel / CA × 100. Résultat attendu : 16,3 %.",["Compte de résultat simplifié, colonne(s) N-1 et N : Salaires et cotisations sociales, Chiffre d’affaires.","Poids du personnel = personnel / CA × 100. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 387 / 2 370 × …"]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","[QCM q3 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le poids des charges de personnel dans le CA N ?","Charges de personnel / chiffre d’affaires × 100","Poids du personnel = personnel / CA × 100. Dans le cas : 16,3 %.",[]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","5. Calculez la marge commerciale rapportée aux ventes de marchandises N.","38 %","Marge sur ventes = marge commerciale / ventes de marchandises × 100. Résultat attendu : 38 %.",["Compte de résultat simplifié, colonne(s) N-1 et N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé).","Marge sur ventes = marge commerciale / ventes de marchandises × 100. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 901 / 2 370 × …"]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","[QCM q4 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la marge commerciale rapportée aux ventes de marchandises N ?","Marge commerciale / ventes de marchandises × 100","Marge sur ventes = marge commerciale / ventes de marchandises × 100. Dans le cas : 38 %.",[]],["DST6 · EMLV · Validation · Validation · Sport des Terrasses","[QCM q5] Le CA augmente de 7,1 % et le résultat net de 52 k€. Quelle conclusion est étayée ?","Les deux progressent ; il faut examiner prix, volumes et charges pour expliquer l’évolution du résultat.","7,1 % est un taux et 52 k€ une variation en montant. Ces évolutions ne suffisent pas à identifier une cause ni à chiffrer un flux de trésorerie.",[]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","1. Quelle précaution de diagnostic est justifiée ?","Il faut croiser résultat, bilan et flux avant de conclure.","Réponse attendue : Il faut croiser résultat, bilan et flux avant de conclure.. Une marge rapporte un résultat aux ventes. Elle ne suffit pas à mesurer les liquidités ou la capacité à financer une dépense ; confrontez-la aux dettes du bilan et aux flux.",[]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","2. Calculez la marge d’exploitation N : RE / CA × 100.","8 %","Marge d’exploitation = RE / CA × 100. Résultat attendu : 8 %.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation, Dotations aux amortissements, Chiffre d’affaires.","Marge d’exploitation = RE / CA × 100. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 168 / 2 088 × …"]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","[QCM q1 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la marge d’exploitation N ?","Résultat d’exploitation / CA × 100","Marge d’exploitation = RE / CA × 100. Dans le cas : 8 %.",[]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","3. Calculez la marge nette N : RN / CA × 100.","5.8 %","Marge nette = RN / CA × 100. Résultat attendu : 5,8 %.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation, Dotations aux amortissements, Produits financiers, Intérêts et charges financières, Impôt sur les bénéfices, Chiffre d’affaires.","Marge nette = RN / CA × 100. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 121 / 2 088 × …"]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","[QCM q2 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la marge nette N ?","Résultat net / CA × 100","Marge nette = RN / CA × 100. Dans le cas : 5,8 %.",[]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","4. Calculez le poids des charges externes dans le CA N.","9.2 %","Poids externe = charges externes / CA × 100. Résultat attendu : 9,2 %.",["Compte de résultat simplifié, colonne(s) N : Autres achats et charges externes, Chiffre d’affaires.","Poids externe = charges externes / CA × 100. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 192 / 2 088 × …"]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","[QCM q3 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le poids des charges externes dans le CA N ?","Charges externes / CA × 100","Poids externe = charges externes / CA × 100. Dans le cas : 9,2 %.",[]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","5. Calculez le poids des intérêts dans l’EBE N : intérêts / EBE × 100.","3.5 %","Poids des intérêts = intérêts / EBE × 100 si l’EBE est positif. Résultat attendu : 3,5 %.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation, Intérêts et charges financières.","Poids des intérêts = intérêts / EBE × 100 si l’EBE est positif. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 7 / 201 × …"]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","[QCM q4 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le poids des intérêts dans l’EBE N ?","Intérêts / EBE × 100","Poids des intérêts = intérêts / EBE × 100 si l’EBE est positif. Dans le cas : 3,5 %.",[]],["DST7 · EMLV · Validation · Validation · Épicerie des Halles","[QCM q5] Pour 100 € de CA, la marge d’exploitation est d’environ 8,0 % et la marge nette de 5,8 %. Que lire ?","On obtient environ 8,0 € de résultat d’exploitation et 5,8 € de résultat net ; intérêts et impôt interviennent ici entre les deux.","Les deux taux ont le même dénominateur, le CA. Leurs numérateurs se situent à des étapes différentes du compte de résultat.",[]],["DST8 · EMLV · Validation · Validation · Mobilier des Ateliers","1. Quelle précaution de diagnostic est justifiée ?","Il faut croiser résultat, bilan et flux avant de conclure.","Réponse attendue : Il faut croiser résultat, bilan et flux avant de conclure.. Un résultat positif peut coexister avec un flux d’exploitation négatif : les ventes à crédit, les stocks et les délais fournisseurs décalent les entrées et sorties d’argent.",[]],["DST8 · EMLV · Validation · Validation · Mobilier des Ateliers","2. Calculez le flux de trésorerie d’exploitation N par la méthode indirecte.","-1 k€","Flux d’exploitation = RN + amortissements − variation du BFR. Résultat attendu : -1 k€.",["Compte de résultat simplifié, colonne(s) N-1 et N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation, Dotations aux amortissements, Produits financiers, Intérêts et charges financières, Impôt sur les bénéfices. Bilan au 31 décembre, colonne(s) N-1 et N : Stocks, Créances clients, Dettes fournisseurs, Dettes fiscales et sociales.","Flux d’exploitation = RN + amortissements − variation du BFR. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : 15 + 106 − variation des stocks − …"]],["DST8 · EMLV · Validation · Validation · Mobilier des Ateliers","[QCM q1 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le flux de trésorerie d’exploitation N par la méthode indirecte ?","Résultat net + amortissements − augmentation du BFR","Flux d’exploitation = RN + amortissements − variation du BFR. Dans le cas : -1 k€.",[]],["DST8 · EMLV · Validation · Validation · Mobilier des Ateliers","3. Calculez la variation totale de trésorerie N.","-89 k€","Variation totale = flux d’exploitation + flux d’investissement + flux de financement. Résultat attendu : -89 k€.",["Compte de résultat simplifié, colonne(s) N-1 et N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Production vendue de biens et services, Production stockée, Matières consommées, Autres achats et charges externes, Salaires et cotisations sociales, Impôts et taxes d’exploitation, Dotations aux amortissements, Produits financiers, Intérêts et charges financières, Impôt sur les bénéfices. Bilan au 31 décembre, colonne(s) N-1 et N : Stocks, Créances clients, Dettes fournisseurs, Dettes fiscales et sociales. Opérations de trésorerie complémentaires en N, colonne(s) N : Acquisitions d’immobilisations payées, Nouveaux emprunts encaissés, Capital des emprunts remboursé, Dividendes payés.","Variation totale = flux d’exploitation + flux d’investissement + flux de financement. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : (-1) + (-264) + …"]],["DST8 · EMLV · Validation · Validation · Mobilier des Ateliers","[QCM q2 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la variation totale de trésorerie N ?","Additionner les flux signés d’exploitation, d’investissement et de financement","Variation totale = flux d’exploitation + flux d’investissement + flux de financement. Dans le cas : -89 k€.",[]],["DST8 · EMLV · Validation · Validation · Mobilier des Ateliers","4. Retrouvez les disponibilités de clôture N.","587 k€","Trésorerie de clôture = trésorerie d’ouverture + variation totale. Résultat attendu : 587 k€.",["Bilan au 31 décembre, colonne(s) N-1 et N : Disponibilités.","Trésorerie de clôture = trésorerie d’ouverture + variation totale. Cette opération isole la grandeur demandée ; les postes déjà inclus dans un solde ne doivent pas être retirés une deuxième fois.","Premier remplacement : Trésorerie d’ouverture 676 + variation totale calculée précédemment."]],["DST8 · EMLV · Validation · Validation · Mobilier des Ateliers","[QCM q3 – méthode] Méthode (hors barème) : quelle opération permet de déterminer les disponibilités de clôture N ?","Trésorerie d’ouverture + variation totale signée de trésorerie","Trésorerie de clôture = trésorerie d’ouverture + variation totale. Dans le cas : 587 k€.",[]],["DST8 · EMLV · Validation · Validation · Mobilier des Ateliers","[QCM q4] Quel diagnostic croise correctement le compte de résultat, le bilan et les flux ?","Le bénéfice est de 15 k€, les créances augmentent de 141 k€ et l’exploitation consomme 1 k€ ; vérifier l’ancienneté des créances.","Des créances en hausse absorbent de la trésorerie. Leur ancienneté aide à distinguer croissance des ventes, délais contractuels et retards ; les investissements constituent un flux distinct.",[]],["DST8 · EMLV · Validation · Validation · Mobilier des Ateliers","[QCM q5] Quelle action RH permet de traiter les retards de paiement sans promettre un gain non vérifié ?","Coordonner vente, facturation et relance ; analyser les litiges, puis suivre la part des factures échues.","Une coordination ciblée peut réduire les retards évitables. Vérifier d’abord l’origine des litiges, puis suivre les factures échues plutôt que le seul CA.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","1. Quel poste du bilan correspond à une vente non encore encaissée ?","Créances clients","Réponse attendue : Créances clients. Une vente réalisée à crédit donne à l’entreprise un droit au paiement : une créance client. Elle ne devient une disponibilité qu’au règlement.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","2. Calculez la variation des stocks.","40 k€","Variation = stock N − stock N-1 : on mesure une différence entre deux photographies. Résultat attendu : 40 k€.",["Bilan au 31 décembre, colonne(s) N-1 et N : Stocks.","Variation = stock N − stock N-1 : on mesure une différence entre deux photographies.","Premier remplacement : 150 − 110 ; conservez le signe."]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e2 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la variation des stocks ?","Stock à la clôture − stock à l’ouverture","Variation = stock N − stock N-1 : on mesure une différence entre deux photographies. Dans le cas : 40 k€.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","3. Calculez la marge commerciale N.","594 k€","MC = ventes de marchandises − coût vendu : on isole ce qui reste de l’achat-revente. Résultat attendu : 594 k€.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé).","MC = ventes de marchandises − coût vendu : on isole ce qui reste de l’achat-revente.","Premier remplacement : 1 650 − 1 056 ; terminez la soustraction."]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e3 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la marge commerciale N ?","Ventes de marchandises − coût des marchandises vendues","MC = ventes de marchandises − coût vendu : on isole ce qui reste de l’achat-revente. Dans le cas : 594 k€.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","4. Calculez la valeur ajoutée N.","396 k€","VA = MC − charges externes : l’activité est ici uniquement commerciale. Résultat attendu : 396 k€.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé), Autres achats et charges externes.","VA = MC − charges externes : l’activité est ici uniquement commerciale.","Premier remplacement : 594 − 198 ; terminez la soustraction."]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e4 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la valeur ajoutée N ?","Marge commerciale − consommations externes dans cette activité uniquement commerciale","VA = MC − charges externes : l’activité est ici uniquement commerciale. Dans le cas : 396 k€.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","5. Calculez l’EBE N.","118 k€","EBE = VA − personnel − taxes : on reste avant amortissements et finance. Résultat attendu : 118 k€.",["Compte de résultat simplifié, colonne(s) N : Salaires et cotisations sociales, Impôts et taxes d’exploitation.","EBE = VA − personnel − taxes : on reste avant amortissements et finance.","Premier remplacement : 396 − 264 − …"]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e5 – méthode] Méthode (hors barème) : quelle opération permet de déterminer l’EBE N ?","Valeur ajoutée + subventions d’exploitation − charges de personnel − impôts et taxes d’exploitation","EBE = VA − personnel − taxes : on reste avant amortissements et finance. Dans le cas : 118 k€.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","6. Calculez le résultat d’exploitation N.","73 k€","RE = EBE − amortissements : on tient compte de la consommation des équipements. Résultat attendu : 73 k€.",["Compte de résultat simplifié, colonne(s) N : Dotations aux amortissements.","RE = EBE − amortissements : on tient compte de la consommation des équipements.","Premier remplacement : 118 − 45 ; terminez la soustraction."]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e6 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le résultat d’exploitation N ?","EBE − dotations aux amortissements, en l’absence d’autres éléments d’exploitation","RE = EBE − amortissements : on tient compte de la consommation des équipements. Dans le cas : 73 k€.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","7. Calculez le RCAI N.","64 k€","RCAI = RE + produits financiers − intérêts : on intègre le coût du financement. Résultat attendu : 64 k€.",["Compte de résultat simplifié, colonne(s) N : Produits financiers, Intérêts et charges financières.","RCAI = RE + produits financiers − intérêts : on intègre le coût du financement.","Premier remplacement : 73 + 0 − …"]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e7 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le RCAI N ?","Résultat d’exploitation + résultat financier","RCAI = RE + produits financiers − intérêts : on intègre le coût du financement. Dans le cas : 64 k€.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","8. Calculez le résultat net N.","48 k€","RN = RCAI − impôt fourni : aucun autre élément n’est indiqué. Résultat attendu : 48 k€.",["Compte de résultat simplifié, colonne(s) N : Impôt sur les bénéfices.","RN = RCAI − impôt fourni : aucun autre élément n’est indiqué.","Premier remplacement : 64 − 16 ; terminez la soustraction."]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e8 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le résultat net N ?","Résultat courant avant impôt − impôt sur les bénéfices, en l’absence d’autres éléments","RN = RCAI − impôt fourni : aucun autre élément n’est indiqué. Dans le cas : 48 k€.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","9. Calculez le taux d’évolution du CA.","10 %","Taux de variation = (N − N-1) / N-1 × 100 : la base est la valeur de départ. Résultat attendu : 10 %.",["Compte de résultat simplifié, colonne(s) N-1 et N : Chiffre d’affaires.","Taux de variation = (N − N-1) / N-1 × 100 : la base est la valeur de départ.","Premier remplacement : (1 650 − 1 500) / 1 500 × …"]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e9 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le taux d’évolution du CA ?","(CA N − CA N−1) / CA N−1 × 100","Taux de variation = (N − N-1) / N-1 × 100 : la base est la valeur de départ. Dans le cas : 10 %.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","10. Calculez la marge commerciale / ventes de marchandises N.","36 %","MC / ventes de marchandises × 100 : on mesure la marge pour 100 euros vendus. Résultat attendu : 36 %.",["Compte de résultat simplifié, colonne(s) N : Ventes de marchandises, Coût des marchandises vendues (déjà calculé).","MC / ventes de marchandises × 100 : on mesure la marge pour 100 euros vendus.","Premier remplacement : 594 / 1 650 × …"]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e10 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la marge commerciale / ventes de marchandises N ?","Marge commerciale / ventes de marchandises × 100","MC / ventes de marchandises × 100 : on mesure la marge pour 100 euros vendus. Dans le cas : 36 %.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","11. Calculez la marge nette N.","2.9 %","RN / CA × 100 : on mesure le résultat final pour 100 euros vendus. Résultat attendu : 2,9 %.",["Compte de résultat simplifié, colonne(s) N : Chiffre d’affaires, Impôt sur les bénéfices.","RN / CA × 100 : on mesure le résultat final pour 100 euros vendus.","Premier remplacement : 48 / 1 650 × …"]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e11 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la marge nette N ?","Résultat net / CA × 100","RN / CA × 100 : on mesure le résultat final pour 100 euros vendus. Dans le cas : 2,9 %.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","12. Calculez le poids du personnel dans le CA N.","16 %","Personnel / CA × 100 : on rapporte le coût du personnel au niveau des ventes. Résultat attendu : 16 %.",["Compte de résultat simplifié, colonne(s) N : Salaires et cotisations sociales, Chiffre d’affaires.","Personnel / CA × 100 : on rapporte le coût du personnel au niveau des ventes.","Premier remplacement : 264 / 1 650 × …"]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e12 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le poids du personnel dans le CA N ?","Charges de personnel / chiffre d’affaires × 100","Personnel / CA × 100 : on rapporte le coût du personnel au niveau des ventes. Dans le cas : 16 %.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","13. Reconstituez le flux de trésorerie d’exploitation N.","32 k€","CFO = RN + amortissements − variation du BFR : stocks et créances absorbent du cash, dettes du cycle en fournissent temporairement. Résultat attendu : 32 k€.",["Compte de résultat simplifié, colonne(s) N-1 et N : Dotations aux amortissements. Bilan au 31 décembre, colonne(s) N-1 et N : Stocks, Créances clients, Dettes fournisseurs, Dettes fiscales et sociales.","CFO = RN + amortissements − variation du BFR : stocks et créances absorbent du cash, dettes du cycle en fournissent temporairement.","Premier remplacement : 48 + 45 − (150 − 110) − …"]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e13 – méthode] Méthode (hors barème) : quelle opération permet de déterminer le flux de trésorerie d’exploitation N ?","Résultat net + amortissements − augmentation du BFR","CFO = RN + amortissements − variation du BFR : stocks et créances absorbent du cash, dettes du cycle en fournissent temporairement. Dans le cas : 32 k€.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","14. Retrouvez la trésorerie finale N.","102 k€","Trésorerie finale = ouverture + exploitation + investissement + financement : on additionne tous les mouvements monétaires. Résultat attendu : 102 k€.",["Bilan au 31 décembre, colonne(s) N-1 et N : Disponibilités. Opérations de trésorerie complémentaires en N, colonne(s) N : Acquisitions d’immobilisations payées, Nouveaux emprunts encaissés, Capital des emprunts remboursé, Dividendes payés.","Trésorerie finale = ouverture + exploitation + investissement + financement : on additionne tous les mouvements monétaires.","Premier remplacement : 140 + 32 − 120 + …"]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e14 – méthode] Méthode (hors barème) : quelle opération permet de déterminer la trésorerie finale N ?","Trésorerie d’ouverture + variation totale signée de trésorerie","Trésorerie finale = ouverture + exploitation + investissement + financement : on additionne tous les mouvements monétaires. Dans le cas : 102 k€.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e15.1] Quel constat chiffré croise correctement les ventes, le résultat et le financement des investissements ?","Le CA augmente de 10 %, le résultat net passe de 100 à 48 k€ et les 32 k€ de flux d’exploitation ne couvrent pas 120 k€ d’investissements.","Le besoin non couvert par le seul flux d’exploitation est de 120 − 32 = 88 k€. Le résultat net et le flux d’exploitation sont deux grandeurs différentes.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e15.2] Les ventes progressent mais la marge commerciale passe de 600 à 594 k€. Quelle conclusion est défendable ?","La marge par euro vendu baisse ; davantage de remises, un changement de mix ou des coûts d’achat plus élevés sont des hypothèses à tester.","Le constat porte sur la marge. Des prix, volumes, coûts ou compositions de ventes différents peuvent produire le même résultat global.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e15.3] Quelles pièces permettent de tester à la fois la baisse de marge et l’immobilisation de liquidités dans le cycle ?","Le détail des prix, quantités et coûts par produit, puis la balance âgée clients et les données de rotation des stocks.","Le détail commercial éclaire prix, mix et coûts. Les échéances des créances et la rotation des stocks expliquent où et combien de temps des fonds restent immobilisés.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e16.1] Quel couple d’actions RH répond aux deux difficultés observées : marge par vente et encaissement ?","Former à la politique de remises et clarifier les rôles entre vente, facturation et relance.","La première action vise les comportements de fixation des prix ; la seconde peut réduire les retards de facturation et le traitement tardif des litiges.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e16.2] Quel mécanisme relie correctement ces actions à la marge et à la trésorerie ?","Mieux maîtriser les remises peut préserver la marge à coût donné ; raccourcir le délai de facturation peut accélérer les encaissements.","Préserver un prix agit sur la marge. Obtenir plus tôt le règlement d’une créance déjà comptabilisée agit sur le calendrier des entrées de trésorerie.",[]],["DST9 · EMLV · Validation · Sujet blanc Collectif Bureau","[QCM e16.3] Quel suivi permet d’évaluer les deux actions sans attribuer trop vite les résultats à la formation ?","Suivre la marge par commande à mix comparable et les créances échues ; examiner aussi les coûts de formation et les litiges préexistants.","Un indicateur doit être relié à chaque action. Les coûts, le mix et les litiges constituent des conditions ou des explications concurrentes à examiner.",[]]]};

