(()=>{'use strict';const groups=[{"id":"dst","chapter":1,"number":"Prépa DST","title":"Exercice pratique et préparation au DST","color":"#425468","soft":"#eff3f8","base":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/","forms":[{"code":"DST1","title":"EMLV · Validation · Validation · Papeterie des Rives","url":"https://docs.google.com/forms/d/e/1FAIpQLScAzvgf00OqEoxvh9wLa5RU4zUeSR8-zx91eYuLd1FQOBfzKg/viewform","topics":"Choisir le bon état pour retrouver une créance ; totaliser les actifs et vérifier l’équilibre.","refs":[{"label":"Lire les documents et sélectionner les données · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/lecture/lecture-1"}]},{"code":"DST2","title":"EMLV · Validation · Validation · Vestiaire des Arts","url":"https://docs.google.com/forms/d/e/1FAIpQLSdqG9us_qqg_phuSlgoG9slBvYaEDeZp5sX1sWQNRQOif9XkQ/viewform","topics":"Passer des achats au coût des marchandises vendues, puis calculer et interpréter la marge.","refs":[{"label":"Construire la marge commerciale · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/marge/marge-1"}]},{"code":"DST3","title":"EMLV · Validation · Validation · Fabrique des Cèdres","url":"https://docs.google.com/forms/d/e/1FAIpQLSenJwP5WlsWJaR39SLak3mhhwSKxu-REpXENmGvpayxYawbCA/viewform","topics":"Distinguer production vendue, stockée et immobilisée ; calculer la valeur ajoutée.","refs":[{"label":"Production et valeur ajoutée · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/production-va/production-va-1"}]},{"code":"DST4","title":"EMLV · Validation · Validation · Services Tramontane","url":"https://docs.google.com/forms/d/e/1FAIpQLSfL_vetAX1_0vKL4oKg5bJmEtG0X2zZ1L6AKe3uOUq61l2WeA/viewform","topics":"Passer de la valeur ajoutée à l’EBE ; distinguer EBE et résultat d’exploitation.","refs":[{"label":"Construire et interpréter l’EBE · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/ebe/ebe-1"}]},{"code":"DST5","title":"EMLV · Validation · Validation · Comptoir Nouvelle Vie","url":"https://docs.google.com/forms/d/e/1FAIpQLSeOgxdtDmG5v3f6f5J3DiJFhBLaJ-u-UWrllYW4x5uLqRcx2A/viewform","topics":"Du résultat d’exploitation au résultat courant puis au bénéfice net.","refs":[{"label":"Du résultat d’exploitation au résultat net · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/resultat/resultat-1"}]},{"code":"DST6","title":"EMLV · Validation · Validation · Sport des Terrasses","url":"https://docs.google.com/forms/d/e/1FAIpQLSduStTgqXienWl4x_UbBTYsNaA_Tf3lc5VSmB1FRRCk7lquYw/viewform","topics":"Calculer une évolution et comparer deux marges ; distinguer pourcentage et points.","refs":[{"label":"Variations et marges rapportées aux ventes · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/evolutions/evolutions-1"}]},{"code":"DST7","title":"EMLV · Validation · Validation · Épicerie des Halles","url":"https://docs.google.com/forms/d/e/1FAIpQLSdEUkHvAl3VUF3Y2Y1aOdnwq36mB0U0utigzMxhhAltGVISyQ/viewform","topics":"Calculer les marges et les ratios pertinents ; préciser le dénominateur et les limites.","refs":[{"label":"Mettre en pratique les ratios retenus · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/ratios/ratios-1"}]},{"code":"DST8","title":"EMLV · Validation · Validation · Mobilier des Ateliers","url":"https://docs.google.com/forms/d/e/1FAIpQLSdDsVCm_Sou7NqyTuOKAcdnCzypTBcsRvnC-IugzduxQIRWlQ/viewform","topics":"Relier bénéfice, BFR et flux d’exploitation avant une décision RH.","refs":[{"label":"Croiser les états et justifier une action RH · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/diagnostic-rh/diagnostic-rh-1"}]},{"code":"DST9","title":"EMLV · Validation · Sujet blanc Collectif Bureau","url":"https://docs.google.com/forms/d/e/1FAIpQLSdWP8_CaYk3GnRHq-CkJ8KZWdXMlj7SNilV2PkgbecyktAlGw/viewform","topics":"Mobiliser bilan, SIG, variations, marges et flux pour justifier un diagnostic complet.","refs":[{"label":"Lire les documents et sélectionner les données · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/lecture/lecture-1"},{"label":"Construire la marge commerciale · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/marge/marge-1"},{"label":"Construire et interpréter l’EBE · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/ebe/ebe-1"},{"label":"Du résultat d’exploitation au résultat net · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/resultat/resultat-1"},{"label":"Variations et marges rapportées aux ventes · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/evolutions/evolutions-1"},{"label":"Croiser les états et justifier une action RH · exemple accompagné","url":"https://azconsultingpro.github.io/emlv-chapitre1-prepa-dst/#case/diagnostic-rh/diagnostic-rh-1"}]}]}],scope="dst";
const q=(s,p=document)=>p.querySelector(s),es=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),line=g=>g.id==='dst'?'Prépa DST':'Module '+g.number,chip=g=>'Chapitre '+g.chapter+' › '+line(g)+' · '+g.title;
const css=".pf-index{--pf:inherit;box-sizing:border-box;margin:clamp(2rem,5vw,4rem) 0 1rem;padding:clamp(1rem,3vw,2rem);border:1px solid #becdce;border-top:5px solid var(--pf,#305464);border-radius:14px;background:#fff;color:#203d44;text-align:left;scroll-margin-top:5rem;font:normal 1rem/1.5 system-ui,sans-serif;min-width:0}.pf-index *{box-sizing:border-box}.pf-index .pf-title{display:block;position:static;inset:auto;background:transparent;color:#18393d;border:0;box-shadow:none;padding:0;margin:0 0 1.2rem}.pf-title small,.pf-series,.pf-reading>span{font:700 .76rem/1.4 system-ui;letter-spacing:.06em;color:var(--pf,#325456)}.pf-index .pf-title h2{font:700 clamp(1.45rem,2.8vw,2.1rem)/1.15 system-ui;color:#17393d;margin:.3rem 0}.pf-index .pf-title p,.pf-index .pf-entry p{margin:.65rem 0;max-width:85ch;color:#2e4549}.pf-index .pf-group{border:1px solid #c4d1d3;border-inline-start:5px solid var(--pf);border-radius:9px;padding:0;margin:.6rem 0;background:white}.pf-index .pf-group>summary{cursor:pointer;display:list-item;font-weight:700;color:#22383c;padding:.75rem 1rem;background:var(--pf-soft,#f2f6f5)}.pf-group>summary small{font-size:.82rem;font-weight:500;margin-inline-start:.75rem;white-space:nowrap}.pf-list{padding:0;margin:0;list-style:none}.pf-index .pf-entry{position:relative;display:block;padding:1.05rem .35rem;margin:0;border:0;border-bottom:1px solid #d6dfe0;background:white;min-width:0}.pf-group .pf-entry{margin:0 .9rem}.pf-entry:last-child{border-bottom:0}.pf-entry-head{display:flex;align-items:baseline;gap:.6rem}.pf-entry .pf-ord{color:white;background:var(--pf,#31595a);border-radius:5px;font:bold .81rem/1.7 system-ui;padding:0 .36rem}.pf-entry h4{font:700 1.06rem/1.4 system-ui;margin:0;color:#18383e;overflow-wrap:anywhere}.pf-reading>span{font-size:.83rem;letter-spacing:0}.pf-reading ul{display:flex;flex-wrap:wrap;gap:.2rem 1.1rem;list-style:none;margin:.18rem 0 .6rem;padding:0}.pf-reading li{margin:0;padding:0}.pf-reading a{font:600 .92rem/1.5 system-ui;text-decoration:underline;text-underline-offset:3px;color:var(--pf,#325456)}.pf-index a.pf-test,.pf-jump{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;border-radius:.45rem;padding:.55rem .8rem;min-height:42px;background:var(--pf,#31595a);color:white;text-decoration:none;border:1px solid transparent;font:650 .9rem/1.35 system-ui;cursor:pointer}.pf-jump{background:#fff;color:#23484d;border-color:#b6c8c9;margin:.3rem 0}.pf-index :is(a,summary):focus-visible,.pf-jump:focus-visible{outline:3px solid #ad6600;outline-offset:3px}.pf-module #emlv-common-nav{border-top:5px solid var(--pf);background:var(--pf-soft)}.pf-module #emlv-common-nav .pf-crumb{color:var(--pf)!important;font:700 .88rem/1.35 system-ui;border-inline-start:3px solid var(--pf);padding-left:.55rem}.pf-module :is(nav,#nav,#navigation) [aria-current=page]:not(.er-native){box-shadow:inset 0 -3px var(--pf)}.pf-module main :is(.hero,.intro-grid,.course-apps):first-child{border-inline-start:5px solid var(--pf);padding-inline-start:clamp(.8rem,2vw,1.5rem)}@media(max-width:640px){.pf-index{padding:.85rem}.pf-group .pf-entry{margin:0 .5rem}.pf-reading ul{display:block}.pf-reading a{display:inline-block;padding:.28rem 0}.pf-entry a.pf-test{min-height:44px}.pf-index summary small{display:block;margin:.2rem 0 0}.pf-module #emlv-common-nav{position:static}}\n";function cssInit(){if(q('#pf-style'))return;const el=document.createElement('style');el.id='pf-style';el.textContent=css+groups.filter(g=>g.chapter===2).map(g=>'#module-switcher [data-module="'+Number(g.number)+'"]{border-left:5px solid '+g.color+';background-color:'+g.soft+'}#module-switcher [data-module="'+Number(g.number)+'"][aria-current="page"]{box-shadow:inset 0 0 0 2px '+g.color+'}').join('');document.head.append(el);}
function entry(f,n){return '<li class="pf-entry"><div class="pf-entry-head"><span class="pf-ord">'+String(n+1).padStart(2,'0')+'</span><div>'+(f.series?'<span class="pf-series">'+es(f.series)+'</span>':'')+'<h4>'+es(f.title)+'</h4></div></div><p><strong>Notions évaluées :</strong> '+es(f.topics)+'</p><div class="pf-reading"><span>Revoir dans le cours</span><ul>'+f.refs.map(ref=>'<li><a href="'+es(ref.url)+'">'+es(ref.label)+'</a></li>').join('')+'</ul></div><a class="pf-test" href="'+es(f.url)+'" target="_blank" rel="noopener noreferrer" aria-label="'+es('Passer le formulaire : '+f.title+' (nouvel onglet)')+'">Passer le formulaire <span aria-hidden="true">↗</span></a></li>';}
function section(gs,chapter){const el=document.createElement('section');el.setAttribute('aria-label',chapter?'Google Forms du chapitre '+chapter:'Google Forms de ce module');el.className='pf-index';el.dataset.pfArea=chapter?'chapitre-'+chapter:gs[0].id;el.id='google-forms-'+el.dataset.pfArea;
let list=g=>'<ol class="pf-list">'+g.forms.map(entry).join('')+'</ol>';el.innerHTML='<header class="pf-title"><small>ÉVALUATIONS DU PARCOURS</small><h2 tabindex="-1">'+(chapter?'Tous les Google Forms du chapitre '+chapter:'Google Forms de ce module')+'</h2><p>'+(chapter?'Ouvrez un module pour retrouver ses formulaires dans l’ordre du parcours.':'Révisez les notions, puis ouvrez le formulaire correspondant à votre étape.')+'</p></header>'+(chapter?gs.map(g=>'<details class="pf-group" style="--pf:'+g.color+';--pf-soft:'+g.soft+'"><summary><span>'+es(line(g)+' · '+g.title)+'</span><small>'+g.forms.length+' formulaires</small></summary>'+list(g)+'</details>').join(''):list(gs[0]));return el;}
function jump(container,el,k){if(!container||q('[data-pf-jump="'+k+'"]',container))return;const b=document.createElement('button');b.type='button';b.className='pf-jump';b.dataset.pfJump=k;b.textContent='Accéder aux Google Forms ↓';b.onclick=()=>{el.scrollIntoView({block:'start'});el.querySelector('h2').focus({preventScroll:true})};container.append(b);}
function portal(){for(const chapter of [1,2]){const host=q('#chapitre-'+chapter);if(!host||q('.pf-index',host))continue;const gs=groups.filter(g=>g.chapter===chapter);for(const a of host.querySelectorAll('a[href]')){const u=a.href.split('#')[0];const g=gs.find(g=>g.base===u);if(!g)continue;a.style.setProperty('--accent',g.color);a.style.setProperty('--tone',g.soft);if(g.id==='dst'){a.style.backgroundColor=g.color;a.style.color='white';}}const el=section(gs,chapter);host.append(el);const h=host.querySelector('h2');if(h){const go=document.createElement('div');h.after(go);jump(go,el,'chapter-'+chapter);}}}
function boot(){cssInit();if(scope==='portail'){portal();return;}const base=q('[data-er-module]');const key=scope==='ch2'?(document.body.dataset.pfModule||({'annuites':'annuites','van':'van','choisir':'choisir','actualisation':'actualisation'}[location.pathname.split('/').filter(Boolean).pop()]||'actualisation')):scope;
const g=groups.find(x=>x.id===key);if(!g)return;const html=document.documentElement;html.style.setProperty('--pf',g.color);html.style.setProperty('--pf-soft',g.soft);html.classList.add('pf-module');const bar=q('#emlv-common-nav');if(bar){const caption=Array.from(bar.children).find(x=>x.tagName==='SPAN');if(caption){caption.textContent=chip(g);caption.classList.add('pf-crumb');}}
const host=q('#app')||q('main');if(!host)return;let scheduled=false;const refresh=()=>{scheduled=false;const h=q('h1',host);if(!h)return;let text=h.textContent.toLowerCase().replace(/\s+/g,' ').trim(),route=location.hash.slice(1).split('/')[0],home=false,ch=false;
switch(key){case'ef':home=text.includes('découvrir les')&&text.includes('états financiers');break;case'bilan':home=text.includes('une photographie à comprendre');break;case'cr':home=text.includes('de la donnée')&&text.includes('décision');break;case'flux':home=text.includes('rentable et manquer de cash');break;case'ratios':home=text.includes('de la lecture des comptes')||text.includes('comprendre les chiffres.');break;case'dst':home=text.includes('exercice pratique')&&text.includes('prépa dst');break;default:home=document.body.dataset.ready==='true'&&document.body.dataset.page==='module';ch=document.body.dataset.ready==='true'&&document.body.dataset.page==='chapitre';}
const active=home||ch;const key2=ch?'chapitre-2':g.id;let el=q('[data-pf-area]',host);if(el&&(!active||el.dataset.pfArea!==key2)){el.remove();el=null}if(active&&!el){el=section(ch?groups.filter(x=>x.chapter===2):[g],ch?2:0);host.append(el);}
let jb=bar&&q('.pf-jump',bar);if(jb&&(!active||jb.dataset.pfJump!==key2||jb._target!==el)){jb.remove();jb=null}if(active&&bar&&!jb){jump(bar,el,key2);q('.pf-jump',bar)._target=el;}};
const queue=()=>{if(!scheduled){scheduled=true;queueMicrotask(refresh)}};refresh();new MutationObserver(queue).observe(host,{childList:true});window.addEventListener('hashchange',queue);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
